"use client";

import * as React from "react";

export function VelocityButtonTailwind({ label = "Execute Edge Deployment" }) {
  const ref = React.useRef<HTMLButtonElement>(null);
  return (
    <button
      ref={ref}
      type="button"
      onPointerMove={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        e.currentTarget.style.setProperty("--x", `${e.clientX - r.left}px`);
        e.currentTarget.style.setProperty("--y", `${e.clientY - r.top}px`);
      }}
      className="group relative overflow-hidden rounded-lg border border-zinc-700 bg-zinc-900 px-5 py-2.5 text-sm font-medium text-zinc-100"
    >
      <span
        className="pointer-events-none absolute inset-0 opacity-0 transition-opacity group-hover:opacity-100"
        style={{ background: "radial-gradient(90px circle at var(--x, 50%) var(--y, 50%), rgba(56,189,248,0.28), transparent 70%)" }}
      />
      <span className="relative z-10">{label}</span>
    </button>
  );
}
